xql_query:
// ============================================================
// Rule: FTG_Antivirus Suspicious File Download
// Vendor: Fortigate
// Objective:
// Detect activity associated with FTG_Antivirus Suspicious File Download.
// Severity: SEV_040_HIGH
// Category: EXECUTION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0002 - Execution
// Technique: T1204 - User Execution
// Technique: T1204.002 - User Execution: Malicious File
// Tactic: TA0001 - Initial Access

// Fonte de dados: logs brutos do Fortinet FortiGate
dataset = fortinet_fortigate_raw  

// Filtro para eventos classificados como "utm:virus"
// Somente aqueles com tipo "infected" e que não foram bloqueados
| filter cat = "utm:virus"
       and FTNTFGTeventtype = "infected"
       and act != "blocked"  

// Criação de campos derivados para facilitar a leitura dos resultados
| alter 
    timestamp = _time,                  // Momento em que o evento ocorreu
    src_ip = src,                       // Endereço IP de origem
    dst_ip = dst,                       // Endereço IP de destino
    action_taken = act,                 // Ação tomada pelo firewall
    file_name = fname,                  // Nome do arquivo identificado
    request_origin = request,           // Origem da requisição
    device_name = _reporting_device_name, // Nome do dispositivo FortiGate que reportou o evento
    arquivo = fname                     // Alias adicional para o nome do arquivo

// Seleção dos campos principais para análise
| fields timestamp, device_name, arquivo, src_ip, dst_ip, action_taken, file_name, request_origin
